'use strict';
const app=document.querySelector('#audit-app'),dialog=document.querySelector('#channel-dialog'),detail=document.querySelector('#channel-detail'),live=document.querySelector('#audit-live');
const state={data:null,query:'',status:'all',category:'all',unreconciled:false,page:1,videoQuery:'',videoChannel:'all',videoEligibility:'all',videoStatus:'all',videoPage:1};let previousFocus=null;
const fields=[['public_uploads_observed','Indexed video IDs (historical route)'],['eligible_current_policy_observed','Indexed videos eligible by current duration rule'],['audio_sources_retained','Audio sources retained'],['video_sources_retained','Video sources retained'],['transcribed_sources','Sources with transcripts'],['analyzed_sources','Sources analyzed']];
const historicalFields=[['eligible_5min_observed','Legacy indexed videos ≥5 minutes'],['historical_caption_analyses','Prior caption records analyzed'],['historical_title_analyses','Prior title records analyzed']];
const finite=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0;
const arr=x=>Array.isArray(x)?x:[];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human=x=>String(x??'Not reported').replaceAll('_',' ');
const number=x=>finite(x)?x.toLocaleString('en-US',{maximumFractionDigits:0}):'Unknown';
const date=x=>x?(/^\d{4}-\d{2}-\d{2}T/.test(String(x))?String(x).slice(0,10):String(x)):'Not checked / not reported';
const source=id=>state.data?.channels.find(c=>c.id===id);
const userExcluded=c=>c.user_requested_exclusion===true||c.user_excluded===true||c.status_reason==='user_requested';
const decision=c=>userExcluded(c)?'exclude':['include','exclude','uncertain'].includes(c.status)?c.status:'uncertain';
const statusLabel=s=>({include:'Include',exclude:'Exclude',uncertain:'Uncertain'}[s]||'Uncertain');
const metric=(c,key)=>{const raw=c.counts?.[key];return raw&&typeof raw==='object'?raw:{value:raw,basis:key.startsWith('historical_')||['public_uploads_observed','eligible_5min_observed'].includes(key)?c.inventory_basis:undefined};};
const value=(c,key)=>{const v=metric(c,key).value;return finite(v)?v:null;};
const count=(c,key)=>finite(value(c,key))?number(value(c,key)):'<span class="unknown" title="Not reconciled or not reported; this is not a zero count">Unknown</span>';
const badge=c=>`<span class="decision ${decision(c)}">${statusLabel(decision(c))}${userExcluded(c)?' · user request':''}</span>`;
const option=(v,label,selected)=>`<option value="${esc(v)}"${v===selected?' selected':''}>${esc(label)}</option>`;
function safeUrl(raw){try{const u=new URL(String(raw));return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function link(raw,label){const u=safeUrl(raw);return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} <svg class="external-icon" viewBox="0 0 12 12" aria-hidden="true"><path d="M3 9 9 3M3 3h6v6" fill="none" stroke="currentColor" stroke-width="1.2"/></svg></a>`:'Source link not reported';}
function historicalRetentionValue(c){const v=c.historical_caption_retention_status??c.counts?.historical_caption_retention_status;return typeof v==='string'?v:typeof v?.status==='string'?v.status:null;}
function historicalRetention(c){const v=historicalRetentionValue(c);return v?human(v):'Unknown / not reconciled';}
function historicalRecordCount(c){const v=c.historical_caption_records??c.counts?.historical_caption_records;if(Array.isArray(v))return v.length;const n=v&&typeof v==='object'?v.value:v;return finite(n)?n:null;}
function historicalRecords(c){return number(historicalRecordCount(c));}
function reason(c){return userExcluded(c)?'Excluded by the user; research classification does not override this choice.':c.status_reason||'A screening rationale has not yet been reported.';}
function filtered(){const q=state.query.trim().toLowerCase();return state.data.channels.filter(c=>(state.status==='all'||decision(c)===state.status)&&(state.category==='all'||c.research_category===state.category)&&(!state.unreconciled||fields.some(([key])=>value(c,key)===null))&&(!q||[c.name,c.handle,c.id,c.research_category,c.status_reason].join(' ').toLowerCase().includes(q)));}
function announce(message){live.textContent=message;}
function table(){
 const records=filtered(),pages=Math.max(1,Math.ceil(records.length/15));state.page=Math.min(state.page,pages);const shown=records.slice((state.page-1)*15,state.page*15);
 return `<div class="result-summary"><p><strong>${records.length}</strong> of ${state.data.channels.length} submitted channel records match. Filters change this view; the export contains every matching row.</p><button type="button" class="secondary" id="export-audit">Export filtered table CSV</button></div><div class="table-wrap" role="region" aria-label="Scrollable channel decisions and coverage table" tabindex="0"><table class="audit-table"><thead><tr>${['Channel / handle','Decision / researched category','Indexed video IDs','Current duration-eligible IDs','Audio retained','Video retained','Current transcribed','Current pipeline analyzed','Historical analyses','Inventory checked'].map(h=>'<th scope="col">'+h+'</th>').join('')}</tr></thead><tbody>${shown.length?shown.map(c=>`<tr><th scope="row"><button type="button" class="source-title" data-channel="${esc(c.id)}">${esc(c.name||c.handle||c.id)}</button><small>${esc(c.handle||c.id)}</small></th><td class="decision-cell">${badge(c)}<small>${esc(human(c.research_category))}</small><small class="reason-snippet">${esc(reason(c))}</small></td><td>${count(c,'public_uploads_observed')}<small>${c.observed_uploads_are_total===true?'Declared public-inventory scope complete':'Total uploads: unknown'}</small></td><td>${count(c,'eligible_current_policy_observed')}<small>${c.minimum_duration_seconds===300?'Bashar ≥5 minutes':'No minimum duration'}</small></td><td>${count(c,'audio_sources_retained')}</td><td>${count(c,'video_sources_retained')}</td><td>${count(c,'transcribed_sources')}</td><td>${count(c,'analyzed_sources')}</td><td><small>Captions: ${count(c,'historical_caption_analyses')}</small><small>Titles: ${count(c,'historical_title_analyses')}</small><small class="reason-snippet history-note">Current raw-caption retention: ${esc(historicalRetention(c))}</small></td><td>${esc(date(c.inventory_checked_at))}</td></tr>`).join(''):'<tr><td colspan="10">No channel records match these filters.</td></tr>'}</tbody></table></div><div class="pager account-pager"><button type="button" class="secondary" data-audit-page="${state.page-1}"${state.page<=1?' disabled':''}>Previous</button><span>Page ${state.page} of ${pages}</span><button type="button" class="secondary" data-audit-page="${state.page+1}"${state.page>=pages?' disabled':''}>Next</button></div>`;
}
function videoChannels(v){return Array.isArray(v.channel_ids)?v.channel_ids:typeof v.channel_id==='string'?[v.channel_id]:[];}
function eligibility(v){if(arr(v.duration_conflict_values).length)return 'conflicted';const minimum=finite(v.minimum_duration_seconds)?v.minimum_duration_seconds:videoChannels(v).some(id=>source(id)?.minimum_duration_seconds===300)?300:0;if(minimum===0)return 'no_minimum';if(v.eligible_under_current_duration_policy===true||v.eligible_current_policy===true)return 'eligible';if(!finite(v.duration_seconds))return 'unknown';return v.duration_seconds>=minimum?'eligible':'short';}
const eligibilityLabels={no_minimum:'No minimum duration applies',eligible:'Meets Bashar 5-minute minimum',short:'Below Bashar 5-minute minimum',unknown:'Duration unknown',conflicted:'Duration conflict',unconfirmed:'Eligibility unconfirmed'};
function historicalCaptionRecorded(v){return state.data.channels.some(c=>arr(c.historical_caption_records).some(r=>(r.videoId||r.video_id)===v.video_id));}
function videoStage(v,kind){const candidates={audio:['audio_status','audio_retained','audio_downloaded'],video:['video_status','video_retained','video_downloaded'],transcript:['transcript_status','transcript_retained','transcribed'],analysis:['analysis_status','analysis_completed','analyzed']}[kind];const key=candidates.find(k=>v[k]!==undefined&&v[k]!==null);if(!key)return 'Unknown';const raw=v[key];if(raw===true)return kind==='analysis'?'Analyzed':'Retained';if(raw===false)return kind==='analysis'?'Not analyzed':'Not retained';if(typeof raw==='string')return human(raw);if(typeof raw?.status==='string')return human(raw.status);return 'Unknown';}
function filteredVideos(){const q=state.videoQuery.trim().toLowerCase();return arr(state.data.videos).filter(v=>(state.videoChannel==='all'||videoChannels(v).includes(state.videoChannel))&&(state.videoEligibility==='all'||eligibility(v)===state.videoEligibility)&&(state.videoStatus==='all'||(v.collection_status||'unreported')===state.videoStatus)&&(!q||[v.video_id,v.title,v.url,...videoChannels(v).flatMap(id=>[id,source(id)?.name,source(id)?.handle])].join(' ').toLowerCase().includes(q)));}
function videoTable(){
 const records=filteredVideos(),pages=Math.max(1,Math.ceil(records.length/15));state.videoPage=Math.min(state.videoPage,pages);const shown=records.slice((state.videoPage-1)*15,state.videoPage*15);
 return `<div class="result-summary video-result-summary"><p><strong>${records.length}</strong> of ${arr(state.data.videos).length} indexed video records match. These account associations are inherited from historical routes; the table does not establish total uploads or reverify the uploader.</p><button type="button" class="secondary" id="export-video-audit">Export filtered video CSV</button></div><div class="table-wrap" role="region" aria-label="Scrollable per-video inventory and coverage table" tabindex="0"><table class="audit-video-table"><thead><tr>${['Indexed video','Historical account route','Duration (seconds)','Duration eligibility','Current audio','Current video','Current transcript','Current analysis','Record status'].map(h=>'<th scope="col">'+h+'</th>').join('')}</tr></thead><tbody>${shown.length?shown.map(v=>`<tr><th scope="row">${link(v.url||v.source_url,v.title||v.video_id)}<small>${esc(v.video_id)}</small></th><td>${videoChannels(v).map(id=>source(id)?'<button type="button" class="source-title" data-channel="'+esc(id)+'">'+esc(source(id).name||id)+'</button>':esc(id)).join('<br>')}</td><td>${finite(v.duration_seconds)?v.duration_seconds.toLocaleString('en-US',{maximumFractionDigits:6}):'<span class="unknown">Unknown</span>'}</td><td>${eligibilityLabels[eligibility(v)]}</td>${['audio','video','transcript','analysis'].map(k=>'<td>'+esc(videoStage(v,k))+'</td>').join('')}<td>${esc(human(v.collection_status))}${historicalCaptionRecorded(v)?'<small>Prior caption analysis recorded; current full-text retention is separate.</small>':''}</td></tr>`).join(''):'<tr><td colspan="9">No indexed video records match these filters.</td></tr>'}</tbody></table></div><div class="pager video-pager"><button type="button" class="secondary" data-video-page="${state.videoPage-1}"${state.videoPage<=1?' disabled':''}>Previous</button><span>Page ${state.videoPage} of ${pages}</span><button type="button" class="secondary" data-video-page="${state.videoPage+1}"${state.videoPage>=pages?' disabled':''}>Next</button></div>`;
}
function videoExplorer(){
 const rows=arr(state.data.videos),ids=[...new Set(rows.flatMap(videoChannels))].sort((a,b)=>(source(a)?.name||a).localeCompare(source(b)?.name||b)),statuses=[...new Set(rows.map(v=>v.collection_status||'unreported'))].sort();
 return `<section id="video-inventory" class="section" tabindex="-1"><div class="section-head"><h2>Inspect individual indexed videos.</h2><p>${new Set(rows.map(v=>v.video_id)).size} distinct video IDs are represented in this historical index. An unknown retention stage stays unknown; metadata availability is not a retained audio, video or transcript.</p></div><div class="toolbar"><label class="search-label">Search video titles and IDs<input id="video-query" type="search" value="${esc(state.videoQuery)}" placeholder="Title, video ID or account name"></label><label>Historical account route<select id="video-channel">${option('all','All indexed account routes',state.videoChannel)}${ids.map(id=>option(id,source(id)?.name||id,state.videoChannel)).join('')}</select></label><label>Recorded duration<select id="video-eligibility">${option('all','All duration states',state.videoEligibility)}${Object.entries(eligibilityLabels).map(([k,v])=>option(k,v,state.videoEligibility)).join('')}</select></label><label>Record status<select id="video-status">${option('all','All record statuses',state.videoStatus)}${statuses.map(k=>option(k,human(k),state.videoStatus)).join('')}</select></label><button type="button" class="secondary" id="clear-video-audit">Clear video filters</button></div><div id="video-results">${videoTable()}</div><p class="table-note">Publisher/RSS records belong in their own inventories unless an exact edition match is established. Current receipt-backed video stages and historical study counts are independent fields.</p></section>`;
}
function updateVideoResults(focusId=null,position=null){document.querySelector('#video-results').innerHTML=videoTable();const control=focusId?document.getElementById(focusId):null;control?.focus({preventScroll:true});if(typeof position==='number')control?.setSelectionRange(position,position);announce(filteredVideos().length+' matching indexed video records.');}
function resetVideoExplorer(){Object.assign(state,{videoQuery:'',videoChannel:'all',videoEligibility:'all',videoStatus:'all',videoPage:1});document.querySelector('#video-inventory').outerHTML=videoExplorer();document.querySelector('#video-query').focus();announce('Video filters cleared.');}
function exportVideoCSV(){const rows=filteredVideos(),headers=['video_id','historical_channel_ids','title','url','duration_seconds','duration_eligibility','collection_status','audio_stage','video_stage','transcript_stage','analysis_stage','historical_caption_analysis_recorded'],body=[headers,...rows.map(v=>[v.video_id,videoChannels(v).join(';'),v.title,v.url||v.source_url,v.duration_seconds,eligibility(v),v.collection_status,...['audio','video','transcript','analysis'].map(k=>videoStage(v,k)),historicalCaptionRecorded(v)])].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n';const url=URL.createObjectURL(new Blob([body],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='subscription-indexed-video-inventory.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Exported '+rows.length+' indexed video records.');}
function render(){
 const channels=state.data.channels,categories=[...new Set(channels.map(c=>c.research_category).filter(Boolean))].sort(),known=channels.filter(c=>value(c,'public_uploads_observed')!==null).length;
 app.innerHTML=`<div class="page-head"><span class="eyebrow">SOURCE SELECTION & ACQUISITION</span><h1>Screen the subscriptions.</h1><p class="lede">Review which channels belong in this research collection, inspect the evidence behind each decision, and separate account inventories from retained media and analyzed text.</p></div><div class="discovery-strip audit-summary"><div><b>${channels.length}</b><span>submitted channel records</span></div>${['include','exclude','uncertain'].map(s=>`<div><b class="${s}">${channels.filter(c=>decision(c)===s).length}</b><span>${statusLabel(s).toLowerCase()} decisions</span></div>`).join('')}</div><div class="scope-note audit-scope"><p>${esc(state.data.scope||'Screening decisions and coverage describe the submitted accounts and the cited research snapshot.')}</p><p><strong>${known} of ${channels.length}</strong> records have matching video IDs in the historical index. Handle associations are inherited, rather than a fresh verification of the uploader. <strong>Total channel uploads remain unknown.</strong> Unknown counts are not zeros.</p></div><div class="audit-explorer-head"><h2>Decisions with their evidence.</h2><p>Open a channel to inspect its research sources, count definitions and collection status. A user-requested exclusion takes precedence over category research.</p></div><div class="toolbar audit-toolbar"><label class="search-label">Search channels and research<input id="audit-query" type="search" value="${esc(state.query)}" placeholder="Channel, handle, category or rationale"></label><label>Screening decision<select id="audit-status">${option('all','All decisions',state.status)}${['include','exclude','uncertain'].map(s=>option(s,statusLabel(s),state.status)).join('')}</select></label><label>Researched category<select id="audit-category">${option('all','All researched categories',state.category)}${categories.map(c=>option(c,human(c),state.category)).join('')}</select></label><label class="check-label"><input id="audit-unreconciled" type="checkbox"${state.unreconciled?' checked':''}>At least one coverage count unknown</label><button type="button" class="secondary" id="clear-audit">Clear filters</button></div><div id="audit-results">${table()}</div>${videoExplorer()}${publisherVideoView()}${publisherAudioView()}${publisherView()}<section id="screening-method" class="section" tabindex="-1"><div class="section-head"><h2>What each field means.</h2><p>Classification describes observed content and research scope. It does not authenticate a claimed identity or establish the truth of a channel’s statements.</p></div><div class="method-grid"><article><h3>Decisions are reviewable.</h3><p>Include, exclude and uncertain remain distinct. Uncertain covers unresolved account identity, mixed formats or insufficient evidence. The record exposes the rationale and sources; it does not infer a channel’s category from its name alone.</p></article><article><h3>Indexed IDs are a partial sample.</h3><p>These IDs come from a historical purposive index joined to inherited handle routes. They are not a fresh channel crawl or a new verification of uploader identity. Total uploads remain unknown. Current collection has no minimum duration for non-Bashar sources; Bashar alone requires 300 seconds. The legacy five-minute subset remains in historical fields and is not the current eligibility rule. Duration conflicts are separately marked.</p></article><article><h3>Acquisition has separate stages.</h3><p>Audio retained, video retained, transcribed sources and analyzed sources are independent receipt-backed counts. Current pipeline counts and historical caption/title analyses have separate columns. Prior analysis can exist without locatable current full text. An available URL is not a download. A transcript is not a retained video. Re-encoded copies do not automatically create another unique source.</p></article><article><h3>Blank does not mean zero.</h3><p>Zero is shown only when the normalized data explicitly report it after reconciliation. Unknown values stay unknown in the table and become empty cells in the CSV. Every supplied count can retain its basis, source link and check date.</p></article></div><div class="download-list"><a href="data.json" download>Download source-linked screening JSON</a><a href="../#/research-update">Open research dashboard</a><a href="../bashar-ra/">Open Bashar & Ra study</a></div></section>`;
 app.setAttribute('aria-busy','false');
}
function updateResults(focusId=null,position=null){document.querySelector('#audit-results').innerHTML=table();const control=focusId?document.getElementById(focusId):null;control?.focus({preventScroll:true});if(typeof position==='number')control?.setSelectionRange(position,position);announce(filtered().length+' matching channel records.');}
function inspect(id){
 const c=source(id);if(!c)return;previousFocus=document.activeElement;
 detail.innerHTML=`<h2 id="channel-title">${esc(c.name||c.handle||c.id)}</h2><p>${esc(c.handle||c.id)} · ${badge(c)}</p><p class="inspection-note">${esc(reason(c))}</p><dl class="record-meta"><dt>Research category</dt><dd>${esc(human(c.research_category))}</dd>${arr(c.roles).length?'<dt>Recorded roles</dt><dd>'+esc(c.roles.map(human).join('; '))+'</dd>':''}${arr(c.medium_attribution?.names).length?'<dt>Publisher-attributed medium(s)</dt><dd>'+esc(c.medium_attribution.names.join('; '))+'<br>'+esc(c.medium_attribution.basis||'')+'</dd>':''}${arr(c.claimed_entities).length?'<dt>Claimed entity labels</dt><dd>'+esc(c.claimed_entities.map(e=>typeof e==='string'?e:e.name||e.label||'').filter(Boolean).join('; '))+'</dd>':''}${c.identity_evidence?'<dt>Account identity evidence</dt><dd>'+esc(c.identity_evidence)+'</dd>':''}<dt>Account identity</dt><dd>${esc(c.id)}${c.youtube_channel_id?'<br>'+esc(c.youtube_channel_id):''}</dd><dt>Research checked</dt><dd>${esc(date(c.checked_at))}</dd><dt>Inventory checked</dt><dd>${esc(date(c.inventory_checked_at))}</dd><dt>Historical index scope</dt><dd>${c.observed_uploads_are_total===true?'Marked complete for the stated public observation scope; unavailable and historical uploads can remain unknown.':'Inherited handle-route associations only; uploader identity is not newly verified. Total uploads remain unknown.'}</dd><dt>True historical upload total</dt><dd>Not established by this screening dataset.</dd></dl><p>${link(c.channel_url,'Open researched channel account')}</p>${arr(state.data.videos).some(v=>videoChannels(v).includes(c.id))?'<p><button type="button" class="secondary" data-open-video-channel="'+esc(c.id)+'">Inspect indexed videos for this historical route</button></p>':''}<dl class="audit-count-list">${fields.map(([key,label])=>{const m=metric(c,key);return `<div><dt>${label}</dt><dd>${count(c,key)}<small>${esc(m.basis||'No account-specific counting basis reported.')}</small>${m.checked_at?'<small>Checked '+esc(date(m.checked_at))+'</small>':''}${m.url?'<small>'+link(m.url,'Count source')+'</small>':''}</dd></div>`;}).join('')}</dl><h3>Historical study coverage</h3><dl class="audit-count-list">${historicalFields.map(([key,label])=>'<div><dt>'+label+'</dt><dd>'+count(c,key)+'<small>'+esc(metric(c,key).basis||'No historical counting basis reported.')+'</small></dd></div>').join('')}</dl><p><strong>Historical caption records documented:</strong> ${historicalRecords(c)}. <strong>Current raw-caption retention:</strong> ${esc(historicalRetention(c))}.</p><p>These counts document prior analysis; they do not establish that the original full texts are retained in the current archive.</p>${c.related_publisher_material?'<h3 class="section">Related publisher material</h3><p>Publisher-linked records have separate provenance and acquisition counts; they do not replace the YouTube inventory.</p><pre>'+esc(JSON.stringify(c.related_publisher_material,null,2))+'</pre>':''}<h3 class="section">Research evidence</h3>${arr(c.evidence).length?'<ul class="evidence-list">'+c.evidence.map(e=>'<li>'+link(e.url,e.label||'Research source')+(e.note?'<p>'+esc(e.note)+'</p>':'')+'</li>').join('')+'</ul>':'<p>Evidence links have not been supplied for this record. Its classification remains inspectable as the recorded research decision.</p>'}${c.evidence_notes?'<p class="inspection-note">'+esc(c.evidence_notes)+'</p>':''}`;
 dialog.showModal();document.querySelector('#close-channel').focus();
}
function csvCell(raw){let s=String(raw??'');if(/^[\t\r\n ]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function exportCSV(){const rows=filtered(),headers=['id','name','handle','screening_decision','research_category','status_reason','channel_url','public_inventory_complete','inventory_checked_at','historical_caption_records','historical_caption_retention_status',...[...fields,...historicalFields].flatMap(([key])=>[key,key+'_basis'])],body=[headers,...rows.map(c=>[c.id,c.name,c.handle,decision(c),c.research_category,c.status_reason,c.channel_url,c.observed_uploads_are_total===true,c.inventory_checked_at,historicalRecordCount(c),historicalRetentionValue(c),...[...fields,...historicalFields].flatMap(([key])=>[value(c,key),metric(c,key).basis])])].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n';const url=URL.createObjectURL(new Blob([body],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='channel-subscription-screening.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Exported '+rows.length+' screened channel records. Unknown counts are empty cells.');}
app.addEventListener('click',event=>{if(event.target.closest('#export-video-audit')){exportVideoCSV();return;}if(event.target.closest('#clear-video-audit')){resetVideoExplorer();return;}const videoPage=event.target.closest('[data-video-page]');if(videoPage&&!videoPage.disabled){state.videoPage=Number(videoPage.dataset.videoPage);updateVideoResults();(app.querySelector('.video-pager button:last-child:not(:disabled)')||app.querySelector('.video-pager button:first-child:not(:disabled)'))?.focus({preventScroll:true});return;}const channel=event.target.closest('[data-channel]');if(channel){inspect(channel.dataset.channel);return;}const page=event.target.closest('[data-audit-page]');if(page&&!page.disabled){state.page=Number(page.dataset.auditPage);updateResults();(app.querySelector('.account-pager button:last-child:not(:disabled)')||app.querySelector('.account-pager button:first-child:not(:disabled)'))?.focus({preventScroll:true});return;}if(event.target.closest('#clear-audit')){Object.assign(state,{query:'',status:'all',category:'all',unreconciled:false,page:1});render();document.querySelector('#audit-query').focus();announce('Screening filters cleared.');}if(event.target.closest('#export-audit'))exportCSV();});
app.addEventListener('input',event=>{if(event.target.id==='video-query'){state.videoQuery=event.target.value;state.videoPage=1;updateVideoResults('video-query',event.target.selectionStart);return;}if(event.target.id==='audit-query'){state.query=event.target.value;state.page=1;updateResults('audit-query',event.target.selectionStart);}});
app.addEventListener('change',event=>{const e=event.target;if(['video-channel','video-eligibility','video-status'].includes(e.id)){state[{ 'video-channel':'videoChannel','video-eligibility':'videoEligibility','video-status':'videoStatus'}[e.id]]=e.value;state.videoPage=1;updateVideoResults(e.id);return;}if(e.id==='audit-status')state.status=e.value;else if(e.id==='audit-category')state.category=e.value;else if(e.id==='audit-unreconciled')state.unreconciled=e.checked;else return;state.page=1;updateResults(e.id);});
dialog.addEventListener('click',event=>{const button=event.target.closest('[data-open-video-channel]');if(!button)return;state.videoChannel=button.dataset.openVideoChannel;state.videoQuery='';state.videoEligibility='all';state.videoStatus='all';state.videoPage=1;document.querySelector('#video-inventory').outerHTML=videoExplorer();previousFocus=document.querySelector('#video-inventory');dialog.close();previousFocus.focus();previousFocus.scrollIntoView({block:'start'});announce('Indexed videos filtered to '+(source(state.videoChannel)?.name||state.videoChannel)+'.');});
document.querySelector('#close-channel').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>previousFocus?.isConnected?previousFocus.focus():document.querySelector('#main').focus());dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const controls=[...dialog.querySelectorAll('button:not(:disabled),a[href],summary,[tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden'),first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});
async function load(){try{app.setAttribute('aria-busy','true');const response=await fetch('data.json');if(!response.ok)throw new Error('The source-linked screening data are not available.');const data=await response.json();if(data.schema_version!==1||!Array.isArray(data.channels)||data.synthetic_fixture_run===true)throw new Error('This is not an admitted screening release.');if(data.channels.some(c=>typeof c.id!=='string')||new Set(data.channels.map(c=>c.id)).size!==data.channels.length)throw new Error('The account identities are inconsistent.');state.data=data;await loadPublisher(data);await loadPublisherInventory(data);await loadPublisherAudio(data);document.querySelector('#snapshot-date').textContent='Research snapshot '+date(data.generated_at||data.checked_at);render();announce('Loaded '+data.channels.length+' screened channel records.');}catch(error){app.setAttribute('aria-busy','false');app.innerHTML=`<div class="error-panel audit-error"><span class="eyebrow">RESEARCH DATA NOT AVAILABLE</span><h1>The screening could not load.</h1><p>${esc(error.message)}</p><button type="button" id="retry-audit">Retry loading data</button><p><a href="../#/research-update">Open the research dashboard</a></p></div>`;document.querySelector('#retry-audit').addEventListener('click',load);announce('Screening data could not load.');}}
load();
